/* ===================== Directory profiles, round 10: technology, real estate, retail, food and drink, travel, transport, government agencies and services, resources and energy =====================
   Two paragraphs each; anything that couldn't be confirmed (including who owns what) is left out. Sizes are bands, not counts. */
const realEstateAgency = (name, where, extra) => ({
  about: [
    `${name} is an Australian real estate agency ${extra || "that sells and manages homes and investment properties"}, ${where}. Its agents appraise properties, run sales campaigns and auctions, and manage rentals for owners and tenants.`,
    "It employs sales agents and sales associates, property managers and leasing consultants, auctioneers, marketing and photography staff, administration and customer service staff, and head office staff in training, technology and finance. Many agent roles are commission-based, and entry-level administration and property management roles are a common way in; a real estate licence or certificate is needed in most states."
  ],
  spec: ["Residential sales", "Property management", "Auctions", "Marketing", "Customer service"],
  roles: ["Sales agent", "Property manager", "Leasing consultant", "Sales associate", "Administration"]
});
const retailBrand = (name, what, extra) => ({
  about: [
    `${name} is ${what}, with stores around Australia and online${extra ? ", " + extra : ""}. Store teams help customers choose products and make purchases, while the online store and customer service team handle orders, deliveries and returns.`,
    "It employs store team members, department and store managers, area managers, distribution and online fulfilment staff, and buying, merchandise, marketing, technology and head office staff. Most roles are in stores, and many people start in casual or part-time sales roles."
  ],
  spec: ["Retail", "Store operations", "Customer service", "Merchandise", "Online"],
  roles: ["Store team member", "Store manager", "Area manager", "Merchandise", "Distribution"]
});
const sesAgency = (name, where) => ({
  about: [
    `${name} is the volunteer-based State Emergency Service for ${where}. It responds to floods, storms and other emergencies, helps with road crash rescue and search operations, and builds community preparedness.`,
    "Most members are volunteers, but it also employs operational and regional staff, emergency management and planning staff, trainers, communications and technology staff, and corporate staff. Its careers page lists paid roles and shows how to volunteer."
  ],
  spec: ["Emergency response", "Flood and storm assistance", "Rescue", "Volunteers", "Community preparedness"],
  hq: where, roles: ["Emergency operations", "Trainer", "Planner", "Volunteer support", "Corporate"]
});
const tourismBody = (name, where) => ({
  about: [
    `${name} is the government tourism organisation for ${where}. It promotes the destination to domestic and international visitors, runs marketing campaigns, supports events and tourism businesses, and works with airlines and the travel trade.`,
    "It employs marketing, digital and content staff, events and industry development staff, research and data staff, trade and international market staff, partnerships staff, and corporate and finance staff. It suits people with tourism, marketing or events backgrounds."
  ],
  spec: ["Destination marketing", "Events", "Tourism industry development", "Research", "Trade and international markets"],
  hq: where, roles: ["Marketing", "Events", "Industry development", "Content", "Research"]
});
